package at.hausgarten.service;
import org.json.*;
/** Real adapters/journal on JVM using synthetic data; no Android persistence claimed. */
public final class BillingTests {
    static int passed;
    interface Task{void run()throws Exception;}
    static void test(String name,Task t)throws Exception{t.run();passed++;System.out.println("PASS "+name);}
    static void yes(boolean b){if(!b)throw new AssertionError();}
    static JSONObject obj(String s)throws Exception{return SyntheticBusinessData.object(s);}
    static JSONObject log(String id,String c,String b)throws Exception{return obj("{\"work_date\":\"2026-10-13\",\"activity\":\"QA Hecke\",\"hours\":3,\"billed\":0}").put("id",id).put("customer_id",c).put("billing_customer_id",b);}
    static JSONObject fixture()throws Exception{return obj("{\"master\":{\"customers\":[{\"id\":\"qa_direct\",\"name\":\"QA Müller\"},{\"id\":\"qa_payer\",\"name\":\"QA Brennter\"},{\"id\":\"qa_site\",\"name\":\"QA Kirschnerhof\",\"billing_mode\":\"via_customer\",\"default_billing_customer_id\":\"qa_payer\"},{\"id\":\"qa_other\",\"name\":\"QA Hofer\",\"billing_mode\":\"via_customer\",\"default_billing_customer_id\":\"qa_payer\"}],\"orders\":[{\"id\":\"qa_order\",\"customer_id\":\"qa_site\",\"title\":\"QA Pflege\"}],\"worklogs\":[],\"invoices\":[],\"photos\":[],\"capabilities\":{\"worklog_compare_and_save\":true,\"entity_compare_and_save\":true}},\"pending\":[]}");}
    public static void main(String[] ignored)throws Exception{ SyntheticBusinessData.verify();
        JSONObject state=fixture(),master=state.getJSONObject("master");
        test("A direct default",()->yes(BillingRules.defaultRecipient("qa_direct","",master).equals("qa_direct")));
        test("B subcontractor default",()->yes(BillingRules.defaultRecipient("qa_site","",master).equals("qa_payer")));
        test("C second site same payer",()->yes(BillingRules.defaultRecipient("qa_other","",master).equals("qa_payer")));
        test("E single override leaves customer unchanged",()->{JSONObject w=log("qa_a","qa_site","qa_site");BillingRules.work(w,null,master);yes(w.getString("billing_customer_id").equals("qa_site"));yes(master.getJSONArray("customers").getJSONObject(2).getString("default_billing_customer_id").equals("qa_payer"));});
        test("F historical missing recipient stays direct",()->{JSONObject old=log("qa_a","qa_site","");JSONObject row=SyntheticBusinessData.object(old.toString());BillingRules.work(row,old,master);yes(row.getString("billing_customer_id").equals("qa_site"));});
        test("D group different sites and direct separately",()->{JSONArray rows=new JSONArray().put(log("qa_a","qa_site","qa_payer")).put(log("b","qa_other","qa_payer")).put(log("qa_c","qa_direct",""));JSONArray groups=BillingRules.groups(rows,master);JSONObject payer=null;for(int i=0;i<groups.length();i++)if(groups.getJSONObject(i).getString("billing_customer_id").equals("qa_payer"))payer=groups.getJSONObject(i);yes(payer!=null&&payer.getDouble("hours")==6&&payer.getJSONArray("work_records").length()==2);});
        test("invalid recipient rejected",()->{try{BillingRules.work(log("qa_a","qa_site","unknown"),null,master);throw new AssertionError();}catch(PixelMcpWriteTools.Rejected expected){}});
        test("billing cycle rejected",()->{try{BillingRules.customerConfig(obj("{\"id\":\"qa_payer\",\"billing_mode\":\"via_customer\",\"default_billing_customer_id\":\"qa_site\"}"),master.getJSONArray("customers"));throw new AssertionError();}catch(PixelMcpWriteTools.Rejected expected){}});
        test("MCP create resolves actual site and recipient",()->{JSONObject args=obj("{\"request_id\":\"qa-billing-create\",\"customer_id\":\"qa_site\",\"work_date\":\"2026-10-13\",\"activity\":\"QA Pflege\",\"hours\":3}");JSONObject row=PixelMcpWriteTools.prepare("create_customer_work_record",args,state,"qa_action");yes(row.getString("customer_id").equals("qa_site")&&row.getString("billing_customer_id").equals("qa_payer"));});
        test("start_work carries recipient not payer as work customer",()->{state.put("work_session",obj("{\"state\":\"IDLE\"}"));JSONObject a=PixelMcpSessionTools.prepare("start_work",obj("{\"request_id\":\"qa-start-billing\",\"customer_id\":\"qa_site\"}"),state);yes(a.getString("customer_id").equals("qa_site")&&a.getString("billing_customer_id").equals("qa_payer"));});
        test("completion retains pinned recipient",()->{state.put("work_session",obj("{\"id\":\"qa_ses_qa\",\"state\":\"STOPPED_PENDING_REVIEW\",\"customer_id\":\"qa_site\",\"billing_customer_id\":\"qa_direct\",\"work_date\":\"2026-10-13\",\"hours\":3}"));JSONObject a=PixelMcpSessionTools.prepare("complete_work_session",obj("{\"request_id\":\"qa-stop-billing\",\"session_id\":\"qa_ses_qa\",\"activity\":\"QA Pflege\"}"),state);yes(a.getString("billing_customer_id").equals("qa_direct"));});
        test("read metadata and groups do not mutate record/hash",()->{master.getJSONArray("worklogs").put(log("qa_a","qa_site","qa_payer"));String before=master.toString();PixelMcpReadTools tools=new PixelMcpReadTools(()->state);JSONObject result=tools.call("get_customer",obj("{\"customer_id\":\"qa_site\"}"));yes(result.getJSONObject("billing_configuration").getString("billing_customer_id").equals("qa_payer"));yes(master.toString().equals(before));JSONObject report=tools.call("get_work_record_summary",obj("{\"group_by_billing_customer\":true}"));yes(report.getJSONObject("data").getJSONArray("billing_groups").length()==1);});
        test("invoice linked recipient cannot silently change",()->{JSONObject old=log("qa_a","qa_site","qa_payer"),changed=log("qa_a","qa_site","qa_direct");JSONArray invoices=new JSONArray().put(obj("{\"id\":\"qa_i\",\"customer_id\":\"qa_payer\",\"positions\":[{\"worklog_id\":\"qa_a\"}]}"));try{WorklogRelationRules.validate(changed,old,new JSONArray(),invoices);throw new AssertionError();}catch(IllegalArgumentException expected){}});
        System.out.println("RESULT "+passed+" billing tests passed");
    }
}
